        if not v:
            return []
        if isinstance(v, dict):
            v = v.values()
        r = []
        for x in v:
            p = pos(x)
            if p is not None:
                r.append(p)
            elif isinstance(x, (list, tuple)):
                for y in x:
                    p = pos(y)
                    if p is not None:
                        r.append(p)
        return r

    s = pos(o.get("self_position")) or (0, 0)
    p = pos(o.get("opponent_position")) or (w - 1, h - 1)
    res = items(o.get("resources"))
    obs = set(items(o.get("obstacles")))
    sp = set(items(o.get("self_path")))
    op = set(items(o.get("opponent_path")))
    block = obs | sp | op
    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    if res:
        tx, ty = min(res, key=lambda q: abs(q[0] - s[0]) + abs(q[1] - s[1]))
        best, bestv = (0, 0), 10**9
        for dx, dy in moves:
