                continue
            v = abs(tx - x) + abs(ty - y)
            if (x, y) == p:
                v += 2
            if v < bestv or (v == bestv and (dx, dy) < best):
                best, bestv = (dx, dy), v
        return [best[0], best[1]]
    best, score = (0, 0), -10**9
    for dx, dy in moves:
        x, y = s[0] + dx, s[1] + dy
        if x < 0 or y < 0 or (w and x >= w) or (h and y >= h) or (x, y) in obs:
            continue
        d = abs(x - p[0]) + abs(y - p[1])
        v = d + (1 if (x, y) not in sp else -1)
        if v > score or (v == score and (dx, dy) < best):
            best, score = (dx, dy), v
    return [best[0], best[1]]

